// Extraer y decodificar los metadatos del webhook
const inputData = $input.first();
const base64Data = inputData.binary.metadata.data;
const decodedString = Buffer.from(base64Data, 'base64').toString('utf-8');
const metadata = JSON.parse(decodedString);

// Preparar los metadatos personalizados
const customMetadata = {
    // Metadatos personalizados para el JSON metadata
    agentId: metadata.agentId,
    documentId: metadata.documentId,
    userId: metadata.userId,
    fileName: metadata.fileName,
    name: metadata.name,
    description: metadata.description,
    fileType: metadata.fileType,
    tags: metadata.tags,

    // Metadatos técnicos
    fileSize: inputData.binary.metadata.fileSize,
    fileMimeType: inputData.binary.file.mimeType,
    uploadedAt: new Date().toISOString(),
    processedAt: new Date().toISOString(),
    source: 'webhook-upload',

    // CAMPOS INDIVIDUALES para la tabla (agregamos esto)
    agent_id: metadata.agentId,
    document_id: metadata.documentId,
    user_id_custom: metadata.userId,
    file_name: metadata.fileName,
    document_name: metadata.name,
    document_description: metadata.description,
    file_type: metadata.fileType,
    document_tags: metadata.tags,
    file_size_info: inputData.binary.metadata.fileSize,
    file_mime_type: inputData.binary.file.mimeType,
    uploaded_at: new Date().toISOString(),
    processed_at: new Date().toISOString(),
    document_source: 'webhook-upload'
};

return {
    json: customMetadata, // Los metadatos van en JSON
    binary: {
        file: inputData.binary.file // El archivo binario se mantiene limpio
    }
};
